local function finite(v)return type(v)=='number'and v==v and math.abs(v)<math.huge end
local function hash(t)
 if t==nil then return 0 end
 if type(t)~='table'then return nil end
 local h=0;for i=1,256 do local v=t[i];if not finite(v)then return nil end;h=(h*31+(v>=0 and v+2 or 1))%2147483647 end;return h
end
local function rect(fn,mid,wanted)
 local a,b,c,d=fn(mid);local got={a,b,c,d}
 if not wanted then return a==nil and b==nil and c==nil and d==nil end
 for i=1,4 do if not finite(got[i])or got[i]~=wanted[i]then return false end end
 return a<c and b<d
end
local P={}
function P.match(input,comp,atlas)
 if input.mapId~='FR_THREE_ISLAND'or input.pair~='sevii_outdoor'or input.width~=24 or input.height~=40 or input.isBorder
   or atlas.w~=256 or atlas.h~=592 or type(atlas.texels)~='function'or type(atlas.hasOver)~='function'
   or type(atlas.underRect)~='function'or type(atlas.overRect)~='function'then return nil end
 for _,s in ipairs(specs)do
  if comp.minX==s.minX and comp.maxX==s.maxX and comp.minY==5 and comp.maxY==6 then
   local valid=true
   for i,row in ipairs(s.cells)do
    local x=s.x0+(i-1)%7;local y=2+math.floor((i-1)/7);local c=input.cellAt(x,y)
    if not c or c.mid~=row[1]or c.collision~=row[2]or c.elevation~=row[3]or c.behavior~=(row[4]~=-1 and row[4]or nil)
      or c.layerType~=row[5]or c.walkable~=(row[6]==1)or c.category~=row[8]then valid=false;break end
   end
   if valid then for mid,h in pairs(s.art)do
    if atlas.hasOver(mid)~=h.has or hash(atlas.texels(mid,'under'))~=h.u or hash(atlas.texels(mid,'over'))~=h.o
      or not rect(atlas.underRect,mid,h.ur)or not rect(atlas.overRect,mid,h.orr)then valid=false;break end
   end end
   if valid then return{name='three-island-native-purple-roof',wallRows=1,flatRoof=false,topArtVerified=true,nativeThreeIsland=true,nativeSoffitSample={mid=655,x=1,y=15},nativeRoofTrimSample={mid=655,x=1,y=15}}end
  end
 end
end
return P
